// csilEncSegment encodes a Segment union as a tagged sum [variant_index, value].
func csilEncSegment(csilV Segment) cborValue {
	switch csilX := csilV.(type) {
	case LiteralSegment:
		return cborArray{cborUint(0), csilEncLiteralSegment(csilX)}
	case SecretSegment:
		return cborArray{cborUint(1), csilEncSecretSegment(csilX)}
	case AmbiguousSegment:
		return cborArray{cborUint(2), csilEncAmbiguousSegment(csilX)}
	case GapSegment:
		return cborArray{cborUint(3), csilEncGapSegment(csilX)}
	default:
		return cborNull{}
	}
}

// csilDecSegment decodes a tagged sum [variant_index, value] into a Segment union.
func csilDecSegment(csilV cborValue) (Segment, error) {
	csilArr, csilOk := csilV.(cborArray)
	if !csilOk || len(csilArr) != 2 {
		var csilZero Segment
		return csilZero, fmt.Errorf("csil cbor: Segment union expects a 2-element array")
	}
	csilIdx, csilIdxErr := cborAsU64(csilArr[0])
	if csilIdxErr != nil {
		var csilZero Segment
		return csilZero, csilIdxErr
	}
	switch csilIdx {
	case 0:
		csilVal, csilErr := (csilDecLiteralSegment)(csilArr[1])
		return csilVal, csilErr
	case 1:
		csilVal, csilErr := (csilDecSecretSegment)(csilArr[1])
		return csilVal, csilErr
	case 2:
		csilVal, csilErr := (csilDecAmbiguousSegment)(csilArr[1])
		return csilVal, csilErr
	case 3:
		csilVal, csilErr := (csilDecGapSegment)(csilArr[1])
		return csilVal, csilErr
	default:
		var csilZero Segment
		return csilZero, fmt.Errorf("csil cbor: unknown Segment variant %d", csilIdx)
	}
}
